    # Mirror of the reference C reader.
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    end = len(data)

    # Reader rejects files larger than 65536 bytes and files too small to
    # contain the 5-byte preamble plus the 2-byte record count.
    if end > 65536:
        return None
    if end < 5 + 2:
        return None

