            "category": category,
            "code": code,
            "created_at": created_at,
            "id": rec_id,
            "priority": priority,
        })

    if offset != end:
        return None

    return {
        "header": {
            "label": h_label,
            "length": h_length,
            "timestamp": h_timestamp,
        },
