MAGIC = 0x84E9AE78


def parse(data: bytes):
    try:
        return _parse(data)
    except Exception:
        return None


def _parse(data):
    if not isinstance(data, (bytes, bytearray)):
        return None
    n = len(data)
    # The reader rejects files larger than 65536 bytes and files too small
    # to hold the 4-byte magic, version byte, record count and 2-byte
    # timestamp.
    if n > 65536 or n < 5 + 2:
        return None
    if data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24) != MAGIC:
        return None
    if data[4] != 0xFD:
        return None

    offset = 5

    def read_number(width):
        nonlocal offset
        if width > n - offset:
            raise ValueError
        value = 0
        for i in range(width):
            value |= data[offset + i] << (8 * i)
        offset += width
        return value

    record_count = read_number(2)
    if record_count > 8:
        return None
    timestamp = read_number(2)
    enabled = read_number(4)
    length = read_number(4)

    records = []
    for _ in range(record_count):
        r_enabled = read_number(1)
        r_flags = read_number(4)
        records.append({"enabled": r_enabled, "flags": r_flags})

    if offset != n:
        return None

    return {
        "header": {
            "enabled": enabled,
            "length": length,
            "timestamp": timestamp,
        },
        "records": records,
    }

