def parse(data: bytes):
    """Parse the binary format used by reader.c.

    Returns the canonical JSON-like structure as a dict, or None if the
    input is malformed (matching the reference reader exactly).
    """
    try:
        n = len(data)
    except Exception:
        return None

    # The reader refuses files larger than 65536 bytes and files shorter
    # than the fixed preamble (5 magic/type bytes + 4-byte record count).
    if n < 9 or n > 65536:
        return None

    # 4-byte little-endian magic, followed by a one-byte type tag.
    if data[0] != 0x22 or data[1] != 0x05 or data[2] != 0x03 or data[3] != 0x2C:
        return None
    if data[4] != 0x6A:
        return None

    offset = 5

    def read(width):
        nonlocal offset
        if offset > n or width > n - offset:
            return None
        value = 0
        for i in range(width):
            value |= data[offset + i] << (8 * i)
        offset += width
        return value

    record_count = read(4)
    if record_count is None or record_count > 8:
        return None

    created_at = read(2)
    if created_at is None:
        return None
    owner = read(4)
    if owner is None:
        return None
    temperature = read(4)
    if temperature is None:
        return None

    records = []
    for _ in range(record_count):
        rec_owner = read(1)
        if rec_owner is None:
            return None
        label = read(4)
        if label is None:
            return None
        score = read(4)
        if score is None:
            return None
        # Key order matches the reader's output: label, owner, score.
        records.append({"label": label, "owner": rec_owner, "score": score})

    # The reader requires that the payload consume the whole file.
    if offset != n:
        return None

    return {
        "header": {
            "created_at": created_at,
            "owner": owner,
            "temperature": temperature,
        },
        "records": records,
    }
