import os, random, subprocess, json, tempfile
from parser import parse

def reader(data):
    p='/tmp/fuzz.bin'
    open(p,'wb').write(data)
    r=subprocess.run(['./reader',p],capture_output=True)
    out=r.stdout.decode().strip()
    if out=='INVALID': return None
    return json.loads(out)

def make():
    kind=random.randrange(6)
    if kind==0:
        return bytes(random.randrange(256) for _ in range(random.randrange(0,60)))
    # structured
    nrec=random.choice([0,0,1,2,3,7,8,9,10,255,2**32-1,random.randrange(0,20)])
    b=bytearray()
    b+=random.choice([b'\x22\x05\x03\x2c', bytes(random.randrange(256) for _ in range(4))])
    b+=bytes([random.choice([0x6a,0x6a,0x6a,random.randrange(256)])])
    if random.random()<0.85:
        b+=nrec.to_bytes(4,'little')
    else:
        b+=bytes(random.randrange(256) for _ in range(random.randrange(0,5)))
    for _ in range(random.randrange(0,12)):
        # varied field lengths, often correct
        w=random.choice([1,2,4,4,4,0,3,5])
        if random.random()<0.8:
            b+=random.randrange(0,2**(8*min(w,4) if w<5 else 32)).to_bytes(w,'little') if w<=4 else bytes(random.randrange(256) for _ in range(w))
        else:
            b+=bytes(random.randrange(256) for _ in range(random.randrange(0,8)))
    if random.random()<0.2:
        b+=bytes(random.randrange(256) for _ in range(random.randrange(1,5)))
    return bytes(b)

